const heartbeatWorker = `-- name: HeartbeatWorker :one
UPDATE workers SET
    status                = 'online',
    -- online_since is the api-owned uptime anchor (PRD #251 M1): PRESERVE it if the worker
    -- is already online with one, else STAMP now() — so repeated heartbeats never move it
    -- and the first heartbeat after an offline gap starts a fresh session. Postgres
    -- evaluates the SET RHS against the OLD row, so status/online_since read the pre-update
    -- tuple (the same mechanism SetRunRunning's ` + "`" + `health = CASE WHEN status='running'` + "`" + ` uses).
    online_since          = CASE WHEN workers.status = 'online' AND workers.online_since IS NOT NULL THEN workers.online_since ELSE now() END,
    last_heartbeat_at     = now(),
    stats_cpu_pct         = $1,
    stats_mem_bytes       = $2,
    stats_mem_limit_bytes = $3,
    stats_source          = $4,
    updated_at            = now()
WHERE id = $5
RETURNING id, user_id, name, token_hash, status, last_heartbeat_at, version, created_at, updated_at, template_declared, template_reported, max_concurrent_runs, stats_cpu_pct, stats_mem_bytes, stats_mem_limit_bytes, stats_source, kind, hosted_size, hosted_generation, docker_enabled, anthropic_secret_id, anthropic_bind_mode, online_since, draining_since, capabilities, ephemeral, ephemeral_run_id
`

type HeartbeatWorkerParams struct {
	StatsCpuPct        pgtype.Float4 `json:"stats_cpu_pct"`
	StatsMemBytes      pgtype.Int8   `json:"stats_mem_bytes"`
	StatsMemLimitBytes pgtype.Int8   `json:"stats_mem_limit_bytes"`
	StatsSource        pgtype.Text   `json:"stats_source"`
	ID                 uuid.UUID     `json:"id"`
}

// Refresh liveness AND overwrite the worker's latest resource sample (PRD #49). The
// stats_* columns are written on EVERY heartbeat — including to NULL when the tick
// carried no stats (a downgraded/older worker or a collector error), so a stale gauge
// self-clears rather than pinning. DISPLAY-ONLY (Decision 5): written here, read only
// by the worker DTOs; no claim/scheduling/sweeper query references stats_ (enforced by
// an M2 regression test). The handler has already validated + clamped these values;
// this statement stores them verbatim.
func (q *Queries) HeartbeatWorker(ctx context.Context, arg HeartbeatWorkerParams) (Worker, error) {
	row := q.db.QueryRow(ctx, heartbeatWorker,
		arg.StatsCpuPct,
		arg.StatsMemBytes,
		arg.StatsMemLimitBytes,
		arg.StatsSource,
		arg.ID,
	)
	var i Worker
	err := row.Scan(
		&i.ID,
		&i.UserID,
		&i.Name,
		&i.TokenHash,
		&i.Status,
		&i.LastHeartbeatAt,
		&i.Version,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.TemplateDeclared,
		&i.TemplateReported,
		&i.MaxConcurrentRuns,
		&i.StatsCpuPct,
		&i.StatsMemBytes,
		&i.StatsMemLimitBytes,
		&i.StatsSource,
		&i.Kind,
		&i.HostedSize,
		&i.HostedGeneration,
		&i.DockerEnabled,
		&i.AnthropicSecretID,
		&i.AnthropicBindMode,
		&i.OnlineSince,
		&i.DrainingSince,
		&i.Capabilities,
		&i.Ephemeral,
		&i.EphemeralRunID,
	)
	return i, err
}

